        "sanskrit": "द्रोणं च भीष्मं च जयद्रथं च कर्णं तथाऽन्यानपि योधवीरान् |\nमया हतांस्त्वं जहि मा व्यथिष्ठा युध्यस्व जेतासि रणे सपत्नान्",
